; ---------------------------------------------------------------------
; RESIDENT: INT 17h printer hook
; ---------------------------------------------------------------------

; INT 17h HOOK  --  jmp [2D6Bh]   ([2D6Bh] เลือกโดย 2E18h จากตาราง 2D67h: 2D72h หรือ 2EC1h)
;   AH=60h / 61h  = คำสั่งส่วนตัวของ THAID: ตั้ง [330Ah] = 1 / 0 แล้วเรียก 32BAh (แปลงรหัสตัวอักษร)
;                    จากนั้น INT A8h  (ตัวขับพิมพ์ที่อยู่ในนี้เอง) แล้วล้าง AH
;   AH=00h = พิมพ์ 1 ตัว -> เรียกตัวกรอง [2DAFh] ก่อน แล้ว chain [271Ch] (INT 17h เดิม)
;   AH อื่น (สถานะ/init) -> chain ตรงๆ

L2D6D:                ; INT 17h handler (hooked)
2D6D  2eff266b2d       jmp word ptr cs:[0x2d6b]

L2D72:                ; INT 17h main path
2D72  80fc60           cmp ah, 0x60                 ; AH == 60h ?
2D75  740e             je 0x2d85
2D77  80fc61           cmp ah, 0x61                 ; AH == 61h ? ไม่ใช่ -> ไปเช็คว่า AH==0
2D7A  7517             jne 0x2d93
2D7C  2ec7060a330000   mov word ptr cs:[0x330a], 0  ; AH=61h: [330Ah] = 0  (โหมดตัวอักษรแบบ 0)
2D83  eb07             jmp 0x2d8c
2D85  2ec7060a330100   mov word ptr cs:[0x330a], 1  ; AH=60h: [330Ah] = 1  (โหมดแบบ 1 -- ใช้เลือกตารางแปลงที่ 32BAh)
2D8C  e82b05           call 0x32ba                  ; แปลงรหัสตัวอักษรใน AL ตามโหมด (ดู 32BAh)
2D8F  cda8             int 0xa8                     ; INT A8h = ตัวขับพิมพ์/ตัวแปลงของ THAID เอง
2D91  32e4             xor ah, ah                   ; ล้าง AH
2D93  84e4             test ah, ah                  ; AH == 0 (พิมพ์ตัวอักษร) ?
2D95  7505             jne 0x2d9c
2D97  2eff16af2d       call word ptr cs:[0x2daf]    ; ใช่ -> ผ่านตัวกรอง/สถานะที่ [2DAFh]
2D9C  2eff2e1c27       ljmp cs:[0x271c]             ; ต่อไป INT 17h เดิมของ BIOS/DOS
2DA1  16               push ss
2DA2  2e07             pop es
2DA4  2e0000           add byte ptr cs:[bx + si], al
2DA7  0000             add byte ptr [bx + si], al
2DA9  0000             add byte ptr [bx + si], al
2DAB  0000             add byte ptr [bx + si], al
2DAD  a5               movsw word ptr es:[di], word ptr [si]
2DAE  2db12d           sub ax, 0x2db1

L2DB1:                ; INT 17h filter idle state
2DB1  3c9b             cmp al, 0x9b                 ; สถานะ IDLE ของตัวกรอง: AL == 9Bh (นำหน้าลำดับพิเศษ) ?
2DB3  7401             je 0x2db6
2DB5  c3               ret                          ; ไม่ใช่: return -> ตัวอักษรถูกส่งต่อไปเครื่องพิมพ์ตามปกติ
2DB6  2ec706af2dbd2d   mov word ptr cs:[0x2daf], 0x2dbd; ใช่: สลับ [2DAFh] = 2DBDh (สถานะรวบรวม)  แล้วตัวอักษรนี้ยังส่งต่อ

L2DBD:                ; INT 17h filter collect state
2DBD  44               inc sp                       ; สถานะ COLLECT: ทิ้ง return address (inc sp x2) = ตัวอักษรนี้ "ไม่ถูกส่ง" ไป chain
2DBE  44               inc sp
2DBF  56               push si
2DC0  2e8b36ad2d       mov si, word ptr cs:[0x2dad] ; SI = พอยน์เตอร์เขียนในบัฟเฟอร์ [2DADh] (เริ่ม 2DA5h)
2DC5  2e8904           mov word ptr cs:[si], ax     ; เก็บ AX ลงบัฟเฟอร์ (AH=0 ทำหน้าที่ตัวจบสตริง)
2DC8  2eff06ad2d       inc word ptr cs:[0x2dad]     ; ขยับพอยน์เตอร์ 1 ไบต์
2DCD  5e               pop si
2DCE  50               push ax
2DCF  2eff36a12d       push word ptr cs:[0x2da1]
2DD4  2eff36a32d       push word ptr cs:[0x2da3]
2DD9  2eff163c0a       call word ptr cs:[0xa3c]     ; เรียกรูทีนภายนอกผ่าน [0A3Ch] (ตัวแปลงลำดับพิมพ์ ยังไม่ได้ตามไปดู)
2DDE  56               push si
2DDF  50               push ax
2DE0  bea52d           mov si, 0x2da5               ; SI = บัฟเฟอร์ 2DA5h : ไล่ส่งทีละไบต์จนเจอ 00
2DE3  2e8a04           mov al, byte ptr cs:[si]     ; AL = ไบต์ถัดไป; 0 = จบ
2DE6  84c0             test al, al
2DE8  741a             je 0x2e04
2DEA  32e4             xor ah, ah
2DEC  9c               pushf 
2DED  2ef606300101     test byte ptr cs:[0x130], 1  ; bit0 ของ [130h] = ส่งผ่านตัวขับภายใน (2ECEh) แทน BIOS?
2DF3  7407             je 0x2dfc
2DF5  0e               push cs
2DF6  e8d500           call 0x2ece                  ; far-call แบบ push cs + call: ไปตัวขับภายใน 2ECEh (ลงท้ายด้วย iret)
2DF9  46               inc si
2DFA  ebe7             jmp 0x2de3
2DFC  2eff1e1c27       lcall cs:[0x271c]            ; ไม่ใช่: lcall INT 17h เดิม [271Ch] ส่งไบต์นี้
2E01  46               inc si
2E02  ebdf             jmp 0x2de3
2E04  58               pop ax                       ; จบ: เก็บกวาด stack
2E05  5e               pop si
2E06  58               pop ax
2E07  58               pop ax
2E08  2ec706ad2da52d   mov word ptr cs:[0x2dad], 0x2da5; รีเซ็ต [2DADh] = 2DA5h (ตัวเขียน)
2E0F  2ec706af2db12d   mov word ptr cs:[0x2daf], 0x2db1; รีเซ็ต [2DAFh] = 2DB1h (กลับสถานะ IDLE) -> iret
2E16  58               pop ax
2E17  cf               iret 

; เลือกตัวขับ INT 17h ตาม AL (0/1):  [130h] bit0 = AL ;  [2D6Bh] = [2D67h + 2*AL]
;   AL=0 -> 2D72h (ส่งผ่าน BIOS)   AL=1 -> 2EC1h (ตัวขับภายใน)
2E18  53               push bx
2E19  33db             xor bx, bx
2E1B  8ad8             mov bl, al
2E1D  d1e3             shl bx, 1
