2E25  2e08063001       or byte ptr cs:[0x130], al
2E2A  2e8b9f672d       mov bx, word ptr cs:[bx + 0x2d67]
2E2F  2e891e6b2d       mov word ptr cs:[0x2d6b], bx
2E34  5b               pop bx
2E35  c3               ret 

